# -*- coding: utf-8 -*-
"""Troca a tipografia dos HTMLs gerados:
   Playfair Display (titulos) + Bebas Neue (destaques de impacto) + Inter/Lato (corpo).
Edita os GERADORES (scripts/), nao os HTMLs de saida."""
import io

# ============================================================ scripts/apresentacao.py
P = 'scripts/apresentacao.py'
s = io.open(P, encoding='utf-8').read()

# --- 1. constante com o <link> do Google Fonts + preconnect
anchor = "NB = 'analise/01_analise_principal.ipynb'"
assert anchor in s
FONTS_CONST = u'''# Tipografia: Playfair Display (titulos) + Bebas Neue (destaques de impacto)
# + Inter/Lato (corpo). Carregada do Google Fonts; os stacks de fallback no CSS
# garantem leitura offline (Georgia p/ titulo, Arial Narrow p/ destaque, Segoe p/ corpo).
FONTS_HREF = ('https://fonts.googleapis.com/css2'
              '?family=Playfair+Display:wght@600;700;800;900'
              '&family=Bebas+Neue'
              '&family=Inter:wght@400;500;600;700'
              '&family=Lato:wght@400;700&display=swap')

'''
s = s.replace(anchor, FONTS_CONST + anchor, 1)

# --- 2. variaveis de fonte no :root
old_root = u"""  --creme-card: #fcfaf4;
  --borda: #e5dfd1;
}"""
new_root = u"""  --creme-card: #fcfaf4;
  --borda: #e5dfd1;
  --fonte-titulo: 'Playfair Display', Georgia, 'Times New Roman', serif;
  --fonte-impacto: 'Bebas Neue', 'Arial Narrow', 'Haettenschweiler', Impact, sans-serif;
  --fonte-corpo: 'Inter', 'Lato', -apple-system, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
}"""
assert old_root in s
s = s.replace(old_root, new_root, 1)

# --- 3. corpo -> Inter/Lato
old_body = u"""  font-family: -apple-system, 'Segoe UI', Roboto, Inter, Helvetica, Arial, sans-serif;
  font-size: 17px;"""
new_body = u"""  font-family: var(--fonte-corpo) !important;
  font-size: 17px;
  -webkit-font-smoothing: antialiased;
  font-feature-settings: 'kern' 1, 'liga' 1;"""
assert old_body in s
s = s.replace(old_body, new_body, 1)

# --- 4. titulos -> Playfair Display
old_h1 = u"""  font-size: 2.1em; font-weight: 800; color: var(--tinta);
  letter-spacing: -0.02em;"""
new_h1 = u"""  font-family: var(--fonte-titulo) !important;
  font-size: 2.35em; font-weight: 800; color: var(--tinta);
  letter-spacing: -0.015em;"""
assert old_h1 in s
s = s.replace(old_h1, new_h1, 1)

old_h2 = u"""  font-size: 1.45em; font-weight: 800; color: var(--accent);
  letter-spacing: -0.01em; margin: 1.9em 0 0.5em; padding-top: 0.4em;"""
new_h2 = u"""  font-family: var(--fonte-titulo) !important;
  font-size: 1.6em; font-weight: 700; color: var(--accent);
  letter-spacing: -0.005em; margin: 1.9em 0 0.5em; padding-top: 0.4em;"""
assert old_h2 in s
s = s.replace(old_h2, new_h2, 1)

old_h3 = u"""  font-size: 1.15em; font-weight: 700; color: var(--accent); margin: 1.5em 0 0.4em;"""
new_h3 = u"""  font-family: var(--fonte-titulo) !important;
  font-size: 1.22em; font-weight: 700; color: var(--accent); margin: 1.5em 0 0.4em;"""
assert old_h3 in s
s = s.replace(old_h3, new_h3, 1)

# --- 5. destaques de impacto: cabecalho de tabela em Bebas Neue
old_th = u"""  background: var(--accent) !important;
  color: #fff !important;
  font-weight: 700;
  padding: 11px 14px;
  text-align: left;
  white-space: nowrap;
}"""
new_th = u"""  background: var(--accent) !important;
  color: #fff !important;
  /* Bebas Neue tem so o peso 400 e caixa alta: sem bold sintetico, com tracking */
  font-family: var(--fonte-impacto) !important;
  font-weight: 400;
  font-size: 15px;
  text-transform: uppercase;
  letter-spacing: 0.055em;
  padding: 11px 14px;
  text-align: left;
  white-space: nowrap;
  line-height: 1.2;
}"""
assert old_th in s
s = s.replace(old_th, new_th, 1)

# --- 6. numeros das tabelas em Inter tabular + classe .impacto reutilizavel
old_tail = u"""
.jp-OutputArea-output .jp-RenderedText pre {
  background: transparent; padding: 4px 8px; margin: 2px 0;
}
"""
new_tail = u"""
.jp-OutputArea-output .jp-RenderedText pre {
  background: transparent; padding: 4px 8px; margin: 2px 0;
}
/* numeros alinhados em coluna (Inter com algarismos tabulares) */
.jp-RenderedHTML td, .jp-RenderedMarkdown td {
  font-family: var(--fonte-corpo);
  font-variant-numeric: tabular-nums;
