const out={};
out.body=f(document.body);
out.h1=f(document.querySelector('.jp-RenderedMarkdown h1'));
out.h2=f(document.querySelector('.jp-RenderedMarkdown h2'));
out.th=f(document.querySelector('.jp-RenderedHTML th'));
out.td=f(document.querySelector('.jp-RenderedHTML td'));
out.p=f(document.querySelector('.jp-RenderedMarkdown p'));
out.thTransform=getComputedStyle(document.querySelector('.jp-RenderedHTML th')).textTransform;
out.loaded=[...document.fonts].filter(x=>x.status==='loaded').map(x=>x.family+' '+x.weight).slice(0,12);
out.fontsReady=document.fonts.status;
out.h2s=[...document.querySelectorAll('.jp-RenderedMarkdown h2')].map(e=>e.textContent.replace('¶','')).slice(0,14);
return out})()

