  font-variant-numeric: tabular-nums;
  font-size: .82rem; font-weight: 600;
  text-align: center !important;
  padding: 14px 18px; border-bottom: none !important;
  border-radius: 4px;
}

/* ============================================================ responsivo */
@media (max-width: 720px) {
  html, body { font-size: 15.5px; }
