}

/* ============================================================ responsivo */
@media (max-width: 720px) {
  html, body { font-size: 15.5px; }
  .card { padding: 24px 20px 26px; border-radius: 12px; }
  .capa { padding: 40px 20px 24px; }
  .capa .jp-RenderedMarkdown h1 { font-size: 1.95rem; }
