var out={vars:[],svg:[],css:[]};
// variaveis CSS definidas no :root
var rs=getComputedStyle(document.documentElement);
for(var i=0;i<rs.length;i++){var p=rs[i];if(p.indexOf('--')===0){var v=rs.getPropertyValue(p).trim();if(/^#|rgb/.test(v))out.vars.push(p+'='+v)}}
// fills de svg
[...document.querySelectorAll('svg *')].slice(0,300).forEach(function(e){var f=e.getAttribute('fill')||getComputedStyle(e).fill;if(f&&!/none|currentColor|rgb\(0, 0, 0\)|rgb\(255, 255, 255\)/.test(f))out.svg.push(f)});
// procura tons coral/rosa em todas as folhas acessiveis
try{[...document.styleSheets].forEach(function(ss){try{[...ss.cssRules].forEach(function(r){var t=r.cssText||'';var m=t.match(/#[0-9a-f]{6}/gi)||[];m.forEach(function(h){var R=parseInt(h.slice(1,3),16),G=parseInt(h.slice(3,5),16),B=parseInt(h.slice(5,7),16);if(R>180&&G>70&&G<170&&B>70&&B<170&&R-G>50)out.css.push(h)})})}catch(e){}})}catch(e){}
out.svg=[...new Set(out.svg)].slice(0,15);out.css=[...new Set(out.css)].slice(0,15);
JSON.stringify(out)

