# -*- coding: utf-8 -*-
"""Troca a paleta do HTML de apresentacao pelas cores da Seazone."""
import io
import json

# ==================================================== 1. gerador: tokens de cor
P = 'scripts/apresentacao.py'
g = io.open(P, encoding='utf-8').read()

old_tokens = u""":root {
  --bg:        #faf8f4;   /* creme quase branco: não estoura na tela */
  --surface:   #fffefb;   /* card, um tom acima do fundo */
  --surface-2: #f4f1ea;   /* blocos de apoio (tags, saída de terminal) */
  --line:      #e9e4d9;   /* bordas suaves */
  --line-soft: #f0ece3;
  --ink:       #1b2320;   /* texto principal */
  --ink-2:     #6f6c63;   /* texto secundário e cabeçalho de tabela */
  --accent:    #0e4f47;   /* verde-escuro sofisticado: títulos */
  --accent-2:  #176f62;   /* variação para h3 e detalhes */
  --wash:      #eef3f1;   /* fundo do callout */
  --destaque:  #edf5ef;   /* linha vencedora */
  --sombra:    0 1px 2px rgba(27,35,32,.04), 0 8px 24px rgba(27,35,32,.06);
  --sombra-img: 0 2px 6px rgba(27,35,32,.06), 0 12px 28px rgba(27,35,32,.10);"""

new_tokens = u""":root {
  /* Paleta Seazone. Os tokens vem do design system do proprio site
     (seazone.com.br): navy --colors-primary-theme #011337, coral do logo
     #F1605D / #FC6058, azul de realce #3758A6, fundo lavanda #EBEBF5. */
  --bg:        #f9f8f5;   /* quase branco com um toque de creme */
  --surface:   #fffffd;   /* card, um tom acima do fundo */
  --surface-2: #f2f3f7;   /* blocos de apoio (tags, saída de terminal) */
  --line:      #e4e5ea;   /* borda Seazone (#E1E2E5), levemente fria */
  --line-soft: #eeeff3;
  --ink:       #19191a;   /* --colors-text-theme */
  --ink-2:     #62656f;   /* --content-theme-secondary */
  --accent:    #011337;   /* navy Seazone: títulos de seção */
  --accent-2:  #3758a6;   /* azul de realce: h3, links, callout */
  --coral:     #f1605d;   /* coral do logo: título da capa */
  --wash:      #f0f2fa;   /* --secondary: fundo do callout */
  --destaque:  #ebebf5;   /* --colors-background-theme: linha vencedora */
  --sombra:    0 1px 2px rgba(1,19,55,.04), 0 8px 24px rgba(1,19,55,.07);
  --sombra-img: 0 2px 6px rgba(1,19,55,.07), 0 12px 28px rgba(1,19,55,.11);"""
assert old_tokens in g, 'tokens claros'
g = g.replace(old_tokens, new_tokens, 1)

old_dark = u"""    --bg:        #141715;
    --surface:   #1b201d;
    --surface-2: #232925;
    --line:      #2c332f;
    --line-soft: #262c29;
    --ink:       #e7e5df;
    --ink-2:     #9d9a91;
    --accent:    #86cfbd;
    --accent-2:  #6cbfab;
    --wash:      #1d2724;
    --destaque:  #1f2b26;
    --sombra:    0 1px 2px rgba(0,0,0,.30), 0 8px 24px rgba(0,0,0,.34);
    --sombra-img: 0 2px 6px rgba(0,0,0,.34), 0 12px 28px rgba(0,0,0,.44);"""
new_dark = u"""    /* no escuro o navy vira o fundo e o azul claro assume os titulos */
    --bg:        #0b1020;
    --surface:   #121a2e;
    --surface-2: #1a2338;
    --line:      #253048;
    --line-soft: #1e2840;
    --ink:       #e8eaf2;
    --ink-2:     #9aa3ba;
    --accent:    #a8c2f0;
    --accent-2:  #8fb0e8;
    --coral:     #ff8a87;
    --wash:      #17203a;
    --destaque:  #1b2440;
    --sombra:    0 1px 2px rgba(0,0,0,.34), 0 8px 24px rgba(0,0,0,.40);
    --sombra-img: 0 2px 6px rgba(0,0,0,.38), 0 12px 28px rgba(0,0,0,.48);"""
assert old_dark in g, 'tokens escuros'
g = g.replace(old_dark, new_dark, 1)

old_h1 = u"""  font-size: 2.6rem; font-weight: 800; letter-spacing: -.025em;
  line-height: 1.14; color: var(--ink); margin: 0 0 .35em;"""
new_h1 = u"""  font-size: 2.6rem; font-weight: 800; letter-spacing: -.025em;
  /* coral da marca. Em 2.6rem/800 conta como texto grande, e o contraste de
     3.19:1 sobre o fundo do card fica acima do minimo AA para esse porte. */
  line-height: 1.14; color: var(--coral); margin: 0 0 .35em;"""
assert old_h1 in g, 'h1'
g = g.replace(old_h1, new_h1, 1)

pares = [
    # filete da capa em coral
    (u"""  content: ''; display: block; height: 3px; width: 72px;
  background: var(--accent); border-radius: 2px; margin-top: 30px;""",
     u"""  content: ''; display: block; height: 3px; width: 72px;
  background: var(--coral); border-radius: 2px; margin-top: 30px;"""),
    # links e callout no azul de realce
    (u"""  color: var(--accent); font-weight: 600;
  text-decoration: underline; text-underline-offset: 3px;
  text-decoration-color: color-mix(in srgb, var(--accent) 35%, transparent);""",
     u"""  color: var(--accent-2); font-weight: 600;
  text-decoration: underline; text-underline-offset: 3px;
  text-decoration-color: color-mix(in srgb, var(--accent-2) 35%, transparent);"""),
    (u"  border-left: 3px solid var(--accent) !important;",
     u"  border-left: 3px solid var(--accent-2) !important;"),
    # o coral marca a linha vencedora: unico uso fora da capa
    (u"""  box-shadow: inset 2px 0 0 var(--accent);
}""",
     u"""  box-shadow: inset 2px 0 0 var(--coral);
}"""),
    (u".jp-RenderedMarkdown ul li::marker { color: var(--accent); }",
     u".jp-RenderedMarkdown ul li::marker { color: var(--accent-2); }"),
]
for velho, novo in pares:
    assert velho in g, velho[:60]
    g = g.replace(velho, novo, 1)

io.open(P, 'w', encoding='utf-8', newline='\n').write(g)
print('OK', P)

# ==================================================== 2. notebook: cores dos dados
PATH = 'analise/01_analise_principal.ipynb'
nb = json.load(io.open(PATH, encoding='utf-8'))

s = ''.join(nb['cells'][21]['source'])
old = u"""COR_POS = 'background-color:#d6efe0; color:#0f5c3c'   # mint
COR_NEG = 'background-color:#fadfd7; color:#8d3924'   # salmao
COR_RUIDO = 'background-color:#f2f1ed; color:#6f6a5e'  # neutro (sinal fraco)
COR_VAZIO = 'background-color:#f8f7f3; color:#c7c2b8'  # sem dado"""
new = u"""# Paleta Seazone: verde de sucesso (#047755) para sinal positivo e a familia
# coral da marca (#F1605D) para negativo, os dois como tinta clara com texto
# escuro. Contraste conferido: 6.8 / 5.2 / 4.7 -- todos acima de AA.
COR_POS = 'background-color:#e4f0ea; color:#0b5c43'   # verde Seazone, tinta clara
COR_NEG = 'background-color:#fde3e2; color:#a63b38'   # coral Seazone, tinta clara
COR_RUIDO = 'background-color:#f1f1f3; color:#6a6a72'  # neutro (sinal fraco)
COR_VAZIO = 'background-color:#f7f7f9; color:#bcbcc4'  # sem dado"""
assert old in s, 'cores deep-dive'
nb['cells'][21]['source'] = s.replace(old, new, 1).splitlines(keepends=True)
nb['cells'][21]['outputs'] = []
nb['cells'][21]['execution_count'] = None

s = ''.join(nb['cells'][24]['source'])
old = u"""    if s.startswith('1ª'): return 'background-color:#e3f0e8; color:#0e4f47; font-weight:700'
    if s.startswith('2ª'): return 'background-color:#edf2e3; color:#4a5a33; font-weight:600'
    if s.startswith('3ª'): return 'background-color:#f7efda; color:#6b5518; font-weight:600'
    return 'background-color:#f1efec; color:#78746c; font-weight:500'"""
new = u"""    if s.startswith('1ª'): return 'background-color:#e9edf9; color:#011337; font-weight:700'
    if s.startswith('2ª'): return 'background-color:#f0f2fa; color:#3758a6; font-weight:600'
    if s.startswith('3ª'): return 'background-color:#f6f1e8; color:#8a5a1e; font-weight:600'
    return 'background-color:#f1f1f3; color:#6e6c72; font-weight:500'"""
assert old in s, 'chips do cartao'
nb['cells'][24]['source'] = s.replace(old, new, 1).splitlines(keepends=True)
nb['cells'][24]['outputs'] = []
nb['cells'][24]['execution_count'] = None

json.dump(nb, io.open(PATH, 'w', encoding='utf-8'), ensure_ascii=False, indent=1)
print('OK', PATH)

# ==================================================== 3. mapa: legenda on-brand
P = 'scripts/map_cell.py'
m = io.open(P, encoding='utf-8').read()
trocas = [
    (u"font-size: 1.25em; color: #0f6b5c;", u"font-size: 1.25em; color: #011337;"),
    (u"background: #fcfaf4; padding: 12px 16px; border: 1px solid #e5dfd1;",
     u"background: #fffffd; padding: 12px 16px; border: 1px solid #e4e5ea;"),
    (u"font-size: 12.5px; color: #26221c; line-height: 1.7;",
     u"font-size: 12.5px; color: #19191a; line-height: 1.7;"),
    (u"color: #26221c; display: block; margin-bottom: 4px;",
     u"color: #011337; display: block; margin-bottom: 4px;"),
]
for velho, novo in trocas:
    assert velho in m, velho[:50]
    m = m.replace(velho, novo, 1)
io.open(P, 'w', encoding='utf-8', newline='\n').write(m)
print('OK', P)

